import asyncio

log = []

async def child(i):
    try:
        await asyncio.sleep(10)
    except asyncio.CancelledError:
        log.append(("cancelled", i))
        try:
            await asyncio.sleep(0.03)
            log.append(("cleanup_done", i))
        except asyncio.CancelledError:
            log.append(("cleanup_interrupted", i))
            raise
        raise

async def run():
    kids = [asyncio.ensure_future(child(i)) for i in range(2)]
    await asyncio.sleep(0.02)
    try:
        await asyncio.gather(*kids)
    except asyncio.CancelledError:
        for k in kids:
            if not k.done():
                k.cancel()
        while True:
            try:
                await asyncio.shield(asyncio.gather(*kids, return_exceptions=True))
                break
            except asyncio.CancelledError:
                continue
        raise

async def main():
    r = asyncio.ensure_future(run())
    await asyncio.sleep(0.03)
    r.cancel()
    try:
        await r
    except asyncio.CancelledError:
        pass

asyncio.run(main())
print(log)
